///|
fn valid_workspace_id(id : String) -> Bool {
  id.length() > 0 &&
  id.length() <= 48 &&
  ((id[0] >= 'a' && id[0] <= 'z') || (id[0] >= '0' && id[0] <= '9')) &&
  id
  .to_array()
  .iter()
  .all(c => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')
}

///|
fn valid_context(value : String) -> Bool {
  value != "" &&
  value
  .to_array()
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '_' ||
    c == '-'
  })
}

///|
fn valid_user(user : String) -> Bool {
  let name = if user.has_suffix("$") {
    user[:user.length() - 1].to_owned()
  } else {
    user
  }
  !text.contains("..") &&
  text
  .split("/")
  .iter()
  .all(part => {
    part != "" &&
    !part.has_prefix(".") &&
    !part.has_suffix(".") &&
    !part.has_suffix(".lock")
  }) &&
  text
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '/' ||
    c == '-' ||
    c == '_' ||
    c == '.'
  })
}

